layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-top: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.54; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 25px; padding-right: 25px; padding-bottom: 25px; padding-left: 25px; transition: all; border-right: none; border-left: none; position: relative }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 3px dotted var(--ryt-border); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-border); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-border); font-family: var(--ryt-font-heading); font-size: 23.2px; font-weight: 700; font-style: normal; line-height: 1.062; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; padding-bottom: 15px; position: relative }
[data-ryt="nav"] a { color: var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.54; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.54; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: color-mix(in srgb, var(--ryt-muted) 65%, transparent); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.54; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-muted) 65%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-top: 8px solid var(--ryt-border); border-right: 8px solid var(--ryt-border); border-bottom: 8px solid var(--ryt-border); border-left: 8px solid var(--ryt-border); border-radius: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-border); border-bottom: 3px dotted var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 21.6px; font-weight: 700; font-style: normal; line-height: 1.141; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; padding-bottom: 15px; border-top: none; border-right: none; border-left: none; position: relative }
[data-ryt="rec-card"] [data-ryt="title"]::after { content: ""; display: block; position: absolute; width: 100%; height: 3px; color: var(--ryt-border); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-bottom: 3px dotted var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 21.6px; font-weight: 700; font-style: normal; line-height: 1.141; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-border); bottom: 2px; left: 0px }
[data-ryt="hero"] h1::after { content: ""; display: block; position: absolute; width: 100%; height: 3px; color: var(--ryt-border); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-bottom: 3px dotted var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 23.2px; font-weight: 700; font-style: normal; line-height: 1.062; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-border); bottom: 2px; left: 0px }
[data-ryt="pitch"]::before { content: "\3e "; display: block; position: absolute; width: 9.60938px; height: 24.6406px; color: var(--ryt-border); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.54; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-border); top: 25px; left: 0px }
